function updatePositionUI(){const p=EuropeanSchools.POSITIONS_2026[$('position').value],needs=p&&(p.requirement==='working_c2'||p.requirement==='english_c2');$('positionRequirementWrap').classList.toggle('hidden',!needs);$('librarianWrap').classList.toggle('hidden',!(p&&p.librarian));if(needs)$('positionRequirementLabel').textContent=p.requirement==='english_c2'?'Καλύπτω την απαίτηση Γ2 στην αγγλική γλώσσα;':'Καλύπτω την απαίτηση Γ2 σε μία γλώσσα εργασίας (Αγγλικά / Γαλλικά / Γερμανικά);';else $('positionLanguageRequirementMet').value='';if(!(p&&p.librarian))$('librarianQualification').value='';}
function v(id){return $(id).value}function c(id){return $(id).checked}
function options(){normalize();return{position:v('position'),branch:v('branch'),totalTeachingYears:v('totalTeachingYears'),ictLevel:v('ictLevel'),blockingIssue:v('blockingIssue'),positionLanguageRequirementMet:v('positionLanguageRequirementMet'),librarianQualification:v('librarianQualification'),phd:c('phd'),master:c('master'),secondPhd:c('secondPhd'),secondMaster:c('secondMaster'),secondDegree:c('secondDegree'),retrainingDegree:c('retrainingDegree'),hostLanguageKey:v('hostLanguageKey'),hostLanguageLevel:v('hostLanguageLevel'),secondWorkingLanguage:v('secondWorkingLanguage'),secondWorkingLevel:v('secondWorkingLevel'),thirdWorkingLanguage:v('thirdWorkingLanguage'),thirdWorkingLevel:v('thirdWorkingLevel'),otherEULanguage:v('otherEULanguage'),otherEULevel:v('otherEULevel'),higherEducationSemesters:v('higherEducationSemesters'),innovativePrograms:v('innovativePrograms'),annualTraining:c('annualTraining'),universityTrainingCount:v('universityTrainingCount'),ministryTrainingHours:v('ministryTrainingHours'),publicAdminTrainingHours:v('publicAdminTrainingHours'),eapAnnualUnits:v('eapAnnualUnits'),eapSemesterUnits:v('eapSemesterUnits'),majorTraining:c('majorTraining'),oralPrerequisiteLanguage:v('oralPrerequisiteLanguage'),oralWorkingLanguage1:v('oralWorkingLanguage1'),oralWorkingLanguage2:v('oralWorkingLanguage2'),thoughtSpeech:v('thoughtSpeech'),interculturalInnovation:v('interculturalInnovation'),curriculumKnowledge:v('curriculumKnowledge')}}
function calculate(){updatePositionUI();const r=EuropeanSchools.calculate(options());$('academicSubtotal').textContent=fmt(r.academic.total)+' / 32';$('serviceSubtotal').textContent=fmt(r.service.total)+' / 18';$('preInterviewTotal').textContent=fmt(r.preInterview);$('academicResult').textContent=fmt(r.academic.total)+' / 32';$('serviceResult').textContent=fmt(r.service.total)+' / 18';if(r.interview.complete){$('interviewSubtotal').textContent=fmt(r.interview.total)+' / 40';$('interviewResult').textContent=fmt(r.interview.total)+' / 40';$('finalTotal').textContent=fmt(r.finalTotal)+' / 90';$('finalHelp').textContent='Τελικό σύνολο τυπικών προσόντων και συνέντευξης.'}else if(r.interview.anyEntered){$('interviewSubtotal').textContent=fmt(r.interview.total)+' / 40 (μερικό)';$('interviewResult').textContent=fmt(r.interview.total)+' / 40 (μερικό)';$('finalTotal').textContent='—';$('finalHelp').textContent='Η συνέντευξη δεν έχει συμπληρωθεί πλήρως.'}else{$('interviewSubtotal').textContent='— / 40';$('interviewResult').textContent='— / 40';$('finalTotal').textContent='—';$('finalHelp').textContent='Συμπλήρωσε όλα τα πεδία της συνέντευξης για τελικό /90.'}const boxes=[];if(r.unanswered.length)boxes.push('<div class="info"><strong>Χρειάζονται ακόμη στοιχεία:</strong><ul style="margin:7px 0 0;padding-left:20px"><li>'+r.unanswered.join('</li><li>')+'</li></ul></div>');if(r.issues.length)boxes.push('<div class="danger"><strong>Έλεγχος προϋποθέσεων:</strong><ul style="margin:7px 0 0;padding-left:20px"><li>'+r.issues.join('</li><li>')+'</li></ul></div>');else if(r.eligibleBeforeInterview)boxes.push('<div class="success"><strong>Ο βασικός έλεγχος πριν από τη συνέντευξη είναι θετικός.</strong> Η πρόσκληση σε συνέντευξη εξαρτάται από τη σχετική κατάταξη.</div>');if(r.warnings.length)boxes.push('<div class="warning"><strong>Παρατηρήσεις:</strong><ul style="margin:7px 0 0;padding-left:20px"><li>'+r.warnings.join('</li><li>')+'</li></ul></div>');$('eligibilityStatus').innerHTML=boxes.join('');return r}
async function copySummary(){const r=calculate(),p=EuropeanSchools.POSITIONS_2026[v('position')],lines=['Μόρια Απόσπασης σε Ευρωπαϊκά Σχολεία','Θέση: '+(p?p.label:'—'),'Α. Κατάρτιση: '+fmt(r.academic.total)+' / 32','Β. Υπηρεσία / εμπειρία: '+fmt(r.service.total)+' / 18','1ο στάδιο Α+Β: '+fmt(r.preInterview)+' / 50','Γ. Συνέντευξη: '+(r.interview.complete?fmt(r.interview.total)+' / 40':'δεν έχει ολοκληρωθεί'),'Τελικό: '+(r.finalTotal===null?'—':fmt(r.finalTotal)+' / 90')];try{await navigator.clipboard.writeText(lines.join('\n'));$('copyBtn').textContent='Αντιγράφηκε ✓';setTimeout(()=>$('copyBtn').textContent='Αντιγραφή σύνοψης',1400)}catch(e){alert(lines.join('\n'))}}
function reset(){document.querySelectorAll('input[type="checkbox"]').forEach(x=>x.checked=false);document.querySelectorAll('input[type="number"]').forEach(x=>x.value='');document.querySelectorAll('input[type="text"]').forEach(x=>x.value='');document.querySelectorAll('select').forEach(x=>x.selectedIndex=0);['higherEducationSemesters','innovativePrograms','universityTrainingCount','ministryTrainingHours','publicAdminTrainingHours','eapAnnualUnits','eapSemesterUnits'].forEach(id=>$(id).value='0');['hostLanguageLevel','secondWorkingLevel','thirdWorkingLevel','otherEULevel'].forEach(id=>$(id).value='none');calculate();$('position').focus()}
ids.forEach(id=>{const e=$(id);if(e){e.addEventListener('input',calculate);e.addEventListener('change',calculate)}});$('copyBtn').addEventListener('click',copySummary);$('resetBtn').addEventListener('click',reset);calculate();})();
</script>
  <script src="assets/common.js"></script>
</body>
</html>
